use crate::domain::{position::Position,trade::Fill}; use rust_decimal::Decimal; use std::collections::HashMap;
#[derive(Default)] pub struct Portfolio { positions:HashMap<String,Position> }
impl Portfolio { pub fn position(&self,mint:&str)->Option<&Position>{self.positions.get(mint)} pub fn apply_entry(&mut self,mint:String,fill:&Fill,price:Decimal,signal_id:String)->Result<(),String>{if fill.output_amount==0{return Err("zero fill".into())}let q=Decimal::from(fill.output_amount);self.positions.entry(mint.clone()).and_modify(|p|{let total=p.quantity+q;p.entry_price_usd=(p.entry_price_usd*p.quantity+price*q)/total;p.quantity=total;p.high_water_price_usd=p.high_water_price_usd.max(price);p.fees_usd+=fill.fees_usd;p.current_value_usd=price*total;p.unrealized_pnl_usd=(price-p.entry_price_usd)*total-p.fees_usd;}).or_insert(Position{mint,quantity:q,entry_price_usd:price,entry_time:fill.confirmed_at,entry_signature:fill.signature.clone(),high_water_price_usd:price,realized_pnl_usd:Decimal::ZERO,unrealized_pnl_usd:-fill.fees_usd,fees_usd:fill.fees_usd,current_value_usd:price*q,signal_id,exit_reason:None});Ok(())} }
